def sliding_windows(lst: list, size: int) -> list[list]:
    if size <= 0:
        raise ValueError("Size must be greater than 0")

    # Check if the list is too small to form a window of the given size
    if len(lst) < size:
        return []

    # Generate all possible windows using list slicing
    windows = [lst[i:i+size] for i in range(len(lst))]

    return windows

