    i = 0

    while i < len(s):
        count_str = ""
        char = s[i]

        # Skip leading zeros in the count string
        while i + 1 < len(s) and s[i+1].isdigit():
            count_str += s[i+1]
            i += 1

        if not count_str:
            decoded.append(char)
        else:
            count = int(count_str)
            decoded.extend([char] * count)

        i += 1

    return ''.join(decoded)

