code:
def expand_ranges(s: str) -> list[int]:
    if not s:
        return []

    # Split the input string into individual ranges
    ranges = s.split(',')

    expanded = []
    for r in ranges:
        parts = r.split('-')
        if len(parts) == 1:
            # Single number range
            num = int(parts[0])
            expanded.append(num)
        elif len(parts) == 2:
            # Range of numbers
            start, end = map(int, parts)
            if start > end:
                raise ValueError(f"Invalid range: {r}")
            expanded.extend(range(start, end + 1))
        else:
            raise ValueError(f"Malformed part: {r}")

    return sorted(expanded)

