def missing_ranges(nums: list[int], lo: int, hi: int) -> list[list[int]]:
    if not nums:
        return []

    # Create a copy of the nums to avoid modifying the original list
    nums_copy = nums.copy()

    # Sort nums by their value
    nums_copy.sort()

    missing = []
    for i in range(len(nums_copy)):
        current = nums_copy[i]
        next_num = None if i == len(nums_copy) - 1 else nums_copy[i + 1]

        if next_num is not None:
            # Check if there's a gap between the current and next number
            if current < lo or next_num > hi:
                missing.append([current, next_num])

    # Handle the edge cases where the first or last number in nums does not match lo or hi
    if nums_copy[0] < lo:
        missing.append([lo, nums_copy[0]])
    if nums_copy[-1] > hi:
        missing.append([nums_copy[-1], hi])

    return missing

