def expand_ranges(s: str) -> list[int]:
    if not s:
        return []

    ranges = []
    current_range = None

    for part in s.split(','):
        # Remove leading/trailing whitespace and hyphens
        part = part.strip().replace('-', '')

        # Check if the part is a single number or a range
        if '-' in part:
            start, end = map(int, part.split('-'))
            current_range = (start, end)
        else:
            current_range = (int(part), int(part))

        # If we have a valid range and it's not overlapping with the previous one, add it to the list
        if current_range and (not ranges or current_range[0] > ranges[-1][1]):
            ranges.append(current_range)

    # Sort the list of ranges by their start time
    ranges.sort(key=lambda x: x[0])

    # Extract all integers from the ranges, handling overlapping ranges correctly
    expanded = []
    for range_ in ranges:
        if not expanded or range_[0] > expanded[-1][1]:
            expanded.append(range_)
        else:
            expanded[-1][1] = max(expanded[-1][1], range_[1])

    # Extract all integers from the expanded list
    expanded_integers = [num for range_ in expanded for num in range(range_[0], range_[1] + 1)]

    return expanded_integers

